pub const fn new(capacity: usize) -> Self {
    let result = Self {
        entries: BTreeMap::new(),
        counter: 0,
        capacity,
    };
    proof! {
        use vstd::set::group_set_axioms;
        use vstd::map::group_map_axioms;
        use vstd::seq_lib::seq_to_set_is_finite;
        reveal(Cache::view);
        reveal(cache_contents_of);
